#!/usr/bin/env node
/*
 * import-shotpattern.mjs — builds src/shotpattern.json from data/extracted/rounds/{date}-{course}/shots.json.
 *
 * src/shotpattern.json is GENERATED by this script. Never hand-edit it: fix the transcription under
 * data/extracted/rounds/ (or the mapping here) and run `npm run import:shots` again.
 *
 * Shot Pattern (Brett's stats app) has no export; its per-round Shot List screens are screenshotted
 * and transcribed into `shots.json` (schema 1: `round`, `driving`, `approach`, `shortGame`,
 * `putting`). Each row becomes one Loop shot record in the src/caddie/shotlog.js shape, marked
 * `source: "shotpattern"`, so the learning loop and the aim warning read them alongside Loop's own.
 * The app bundles the output and seeds it into `bogeyman-matches:shots:v1` at load
 * (`seedShotPatternRecords`, shotlog.js).
 *
 * Miss geometry — only what Shot Pattern gives, never a split of a magnitude it does not have:
 *   driving    derived.lateralMissYds = ±offline (right +, left −); distance component null; totalYds.
 *   approach   derived.missTotalYds (feet ÷ 3, or the `y` value) + missDistSign (+1 long / −1 short)
 *              + missLatSign (+1 right / −1 left); both components null.
 *   short game the same signs from the words; the magnitude is the proximity (toHoleFt ÷ 3).
 *   putting    putt records; speed / line are ±1 or 0 only (see puttRecord).
 * With both components null, applyShotLog / withinRound (learning.js hasMisses) skip every one of
 * these — they can never enter an sd or bias estimate. `tendencies()` reads their signs.
 *
 * Usage:
 *   node scripts/import-shotpattern.mjs           # writes src/shotpattern.json
 *   node scripts/import-shotpattern.mjs --check   # exits 1 if src/shotpattern.json differs from a fresh build
 */

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { newShotRecord, SHOT_SCHEMA } from "../src/caddie/shotlog.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const ROUNDS_DIR = path.join(ROOT, "data/extracted/rounds");
const OUT_PATH = path.join(ROOT, "src/shotpattern.json");

export const BUNDLE_VERSION = 1;
export const SOURCE = "shotpattern";

/* ---------- vocabulary ---------- */

/** Shot Pattern's club names → Loop club ids (src/profile.json clubOrder). `Putter` → a putt record. */
const CLUB_IDS = {
  dr: "Dr", driver: "Dr",
  "2i": "2i", "2hy": "2Hy", "4hy": "4Hy",
  "5i": "5i", "6i": "6i", "7i": "7i", "8i": "8i", "9i": "9i",
  pw: "PW", gw: "GW", sw: "SW", lw: "LW",
  putter: "Putter",
};

/** A club as transcribed → Loop id; null for Unknown Club / a blank. Throws on anything else, so a
 *  transcription slip fails at import instead of landing as a club nobody has. */
export function mapClub(name) {
  if (name == null) return null;
  const k = String(name).trim().toLowerCase();
  if (!k || k === "unknown club" || k === "unknown") return null;
  if (CLUB_IDS[k]) return CLUB_IDS[k];
  throw new Error(`import-shotpattern: unknown club "${name}"`);
}

/** Shot Pattern lie words → { lie, detail }. `deep rough` is Loop's rough with detail "deep". */
const LIES = { tee: "tee", fairway: "fairway", rough: "rough", recovery: "recovery", penalty: "penalty", green: "green", sand: "sand", bunker: "sand" };
export function mapLie(s) {
  if (s == null) return { lie: null, detail: null };
  const k = String(s).trim().toLowerCase();
  if (k === "deep rough") return { lie: "rough", detail: "deep" };
  if (LIES[k]) return { lie: LIES[k], detail: null };
  throw new Error(`import-shotpattern: unknown lie "${s}"`);
}

/** Direction words ("21' short left of target", "long right of hole") → { dist, lat } signs:
 *  dist +1 long / −1 short, lat +1 right / −1 left; null for an axis the words do not name. */
export function missSigns(words) {
  const w = String(words || "").toLowerCase();
  const dist = /\blong\b/.test(w) ? 1 : /\bshort\b/.test(w) ? -1 : null;
  const lat = /\bright\b/.test(w) ? 1 : /\bleft\b/.test(w) ? -1 : null;
  return { dist, lat };
}

const r1 = (v) => Math.round(v * 10) / 10;
const r2 = (v) => Math.round(v * 100) / 100;
const num = (v) => typeof v === "number" && Number.isFinite(v);

/* ---------- one round ---------- */

/**
 * Loop's records carry an ISO `ts`; Shot Pattern gives no times. The importer writes a synthetic,
 * deterministic one — the round date at 12:00:00Z plus one second per shot in playing order — so
 * chronological sorts (learning.js) keep the order and importShots' newer-ts rule has a value. It
 * is ordering only, never a real time.
 */
function tsFor(date, order) {
  return new Date(Date.parse(`${date}T12:00:00.000Z`) + order * 1000).toISOString();
}

function common(ctx, hole, seq) {
  return {
    id: `sp:${ctx.date}:${hole}:${seq}`,
    roundId: null,                       // assigned on the phone (seedShotPatternRecords): the Loop round, else `sp:{key}`
    courseId: null,
    nine: hole <= 9 ? "front" : "back",
    hole,
    shotNo: seq,
    ts: tsFor(ctx.date, ctx.order++),
  };
}

/** A full / finesse / recovery row → a shotlog.js ShotRecord. */
function swingRecord(ctx, hole, seq, { category, club, startLie, startYds, endLie, toHoleFt, toHoleYds, shotType, derived, sg, missNote }) {
  const s = mapLie(startLie), e = mapLie(endLie);
  const base = newShotRecord({
    ...common(ctx, hole, seq),
    start: { lat: null, lng: null, accuracyM: null, distanceToPinYds: num(startYds) ? startYds : null, playsLikeYds: null, frame: null },
    target: null,
    lie: { inferred: null, confidence: null, confirmed: s.lie, quality: null },
    conditions: "normal",
    wind: null,
    recommendation: null,
    club,
    shotType,
    contact: null, strike: null, startLine: null,
    end: {
      lat: null, lng: null, accuracyM: null, lie: e.lie,
      ...(e.detail ? { lieDetail: e.detail } : {}),
      toHoleFt: num(toHoleFt) ? toHoleFt : num(toHoleYds) ? toHoleYds * 3 : null,
      ...(num(toHoleYds) ? { toHoleYds } : {}),
    },
    derived,
    logged: "imported",
    reviewed: true,
  });
  return {
    ...base,
    source: SOURCE,
    ...(s.detail ? { lieDetail: s.detail } : {}),
    // Shot Pattern never knows which caddie line was played, nor a shape or a curve: null, not
    // newShotRecord's "own" / "straight" / 0 defaults (the aggression scorecard skips them).
    linePlayed: null,
    intendedShape: null,
    curve: null,
    sp: { category, sg: num(sg) ? sg : null, missNote: missNote ?? null },
  };
}

/**
 * A putting row (or a putter from off the green) → a putt record. Shot Pattern says only where the
 * ball finished relative to the hole ("short right of hole"), so the grades are ±1 or 0 and NEVER
 * ±2 — there is no magnitude to put a "very short" or a "big push" on:
 *   speed  short −1 / long +1, made 0        line  left −1 / right +1, made 0
 *   breakRead null — the words cannot tell a misread break from a pulled or pushed stroke.
 */
function puttRecord(ctx, hole, seq, { category, distanceFt, made, missNote, sg, startLie = null, endLie = null, toHoleFt = null }) {
  const sgn = made ? { dist: 0, lat: 0 } : missSigns(missNote);
  const s = mapLie(startLie), e = mapLie(endLie);
  return {
    ...common(ctx, hole, seq),
    schema: SHOT_SCHEMA,
    gps: null,
    shotType: "putt",
    logged: "imported",
    reviewed: true,
    source: SOURCE,
    putt: {
      distanceFt: num(distanceFt) ? r2(distanceFt) : null,
      made: !!made,
      speed: sgn.dist ?? null,
      breakRead: null,
      line: sgn.lat ?? null,
    },
    ...(s.lie ? { lie: { inferred: null, confidence: null, confirmed: s.lie, quality: null } } : {}),
    ...(e.lie || num(toHoleFt) ? { end: { lie: e.lie, toHoleFt: num(toHoleFt) ? toHoleFt : null } } : {}),
    sp: { category, sg: num(sg) ? sg : null, missNote: missNote ?? null },
  };
}

function signedDerived(extra) {
  return { distanceMissYds: null, lateralMissYds: null, onTarget: null, intendedYds: null, actualYds: null, ...extra, source: SOURCE };
}

/**
 * One shots.json → { key, date, course, nines, tee, score, sg, complete, holesShort, records }.
 * Order within a hole (seq / shotNo): the drive, the approaches, the short game, the putts, each in
 * the file's own order. Penalty strokes are not rows, so `shotNo` counts records, not strokes.
 */
export function roundFromShots(json, key) {
  if (!json || json.schema !== 1) throw new Error(`import-shotpattern: ${key}: expected schema 1`);
  const r = json.round || {};
  const date = r.date;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date || ""))) throw new Error(`import-shotpattern: ${key}: bad round.date`);
  const ctx = { date, order: 0 };
  const byHole = new Map();
  const put = (hole, row) => { if (!byHole.has(hole)) byHole.set(hole, []); byHole.get(hole).push(row); };
  for (const d of json.driving || []) put(d.hole, { kind: "driving", row: d });
  for (const a of json.approach || []) put(a.hole, { kind: "approach", row: a });
  for (const g of json.shortGame || []) put(g.hole, { kind: "shortGame", row: g });
  for (const p of json.putting || []) put(p.hole, { kind: "putting", row: p });
  const RANK = { driving: 0, approach: 1, shortGame: 2, putting: 3 };

  const records = [];
  const holes = [...byHole.keys()].sort((a, b) => a - b);
  for (const hole of holes) {
    if (!Number.isInteger(hole) || hole < 1 || hole > 18) throw new Error(`import-shotpattern: ${key}: bad hole ${hole}`);
    const rows = byHole.get(hole).map((x, i) => ({ ...x, i })).sort((a, b) => RANK[a.kind] - RANK[b.kind] || a.i - b.i);
    rows.forEach(({ kind, row }, k) => {
      const seq = k + 1;
      if (kind === "driving") {
        const lat = (row.side === "left" ? -1 : 1) * (num(row.offlineYds) ? row.offlineYds : NaN);
        records.push(swingRecord(ctx, hole, seq, {
          category: "driving", club: mapClub(row.club), startLie: "tee",
          startYds: Array.isArray(r.yardsPerHoleSP) ? r.yardsPerHoleSP[hole - 1] ?? null : null,
          endLie: row.endLie, shotType: "full", sg: row.sg,
          missNote: null,                                        // Shot Pattern prints no words on a drive
          derived: signedDerived({
            lateralMissYds: Number.isFinite(lat) ? lat || 0 : null,   // 0 offline stays 0, never −0
            totalYds: num(row.yds) ? row.yds : null,
            missLatSign: Number.isFinite(lat) ? Math.sign(lat) || 0 : null,
            missDistSign: null,
          }),
        }));
        return;
      }
      if (kind === "putting") {
        records.push(puttRecord(ctx, hole, seq, { category: "putting", distanceFt: row.startFt, made: row.result === "make", missNote: row.missNote, sg: row.sg }));
        return;
      }
      const club = mapClub(row.club);
      const s = { dist: row.missDist === "long" ? 1 : row.missDist === "short" ? -1 : null, lat: row.missLat === "right" ? 1 : row.missLat === "left" ? -1 : null };
      const w = missSigns(row.missNote);
      const signs = { dist: s.dist ?? w.dist, lat: s.lat ?? w.lat };
      if (club === "Putter") {
        // a putter from off the green: a putt record (the club rule), filed where Shot Pattern files it
        records.push(puttRecord(ctx, hole, seq, {
          category: kind, distanceFt: num(row.startYds) ? row.startYds * 3 : null, made: false, missNote: row.missNote, sg: row.sg,
          startLie: row.startLie, endLie: row.endLie, toHoleFt: row.toHoleFt,
        }));
        return;
      }
      const startLie = mapLie(row.startLie).lie;
      const shotType = startLie === "recovery" ? "recovery"
        : kind === "shortGame" ? (num(row.startYds) && row.startYds < 50 ? "finesse" : "full")
        : "full";
      const total = kind === "approach"
        ? (num(row.missTotalYds) ? row.missTotalYds : num(row.missTotalFt) ? r1(row.missTotalFt / 3) : null)
        : (num(row.toHoleFt) ? r1(row.toHoleFt / 3) : null);        // short game: the proximity is the miss
      records.push(swingRecord(ctx, hole, seq, {
        category: kind, club, startLie: row.startLie, startYds: row.startYds, endLie: row.endLie,
        toHoleFt: row.toHoleFt, toHoleYds: row.toHoleYds, shotType, sg: row.sg, missNote: row.missNote,
        derived: signedDerived({ missTotalYds: total, missDistSign: signs.dist, missLatSign: signs.lat }),
      }));
    });
  }

  // Holes where the rows (plus one stroke per penalty end lie) do not add up to the score Shot
  // Pattern printed — a transcription still missing rows (putting 10–12 on the first file).
  const holesShort = [];
  if (Array.isArray(r.scores)) {
    r.scores.forEach((score, i) => {
      const hole = i + 1;
      const recs = records.filter((x) => x.hole === hole);
      const penalties = recs.filter((x) => x.end?.lie === "penalty").length;
      const strokes = recs.length + penalties;
      if (num(score) && strokes !== score) holesShort.push({ hole, records: recs.length, penalties, strokes, score });
    });
  }

  return {
    key, date,
    course: r.course ?? null,
    location: r.location ?? null,
    nines: Array.isArray(r.nines) ? r.nines : null,
    tee: r.tee ?? null,
    score: num(r.score) ? r.score : null,
    sg: r.sg ?? null,
    complete: json.complete === true,
    holesShort,
    records,
  };
}

/** Every round → the bundle. `generated` is the build date (normalized out by --check). */
export function buildBundle(entries, generated) {
  return {
    version: BUNDLE_VERSION,
    generated,
    rounds: entries.map(({ key, json }) => roundFromShots(json, key)).sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.key < b.key ? -1 : 1)),
  };
}

export function readRounds(dir = ROUNDS_DIR) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).sort()
    .filter((k) => fs.existsSync(path.join(dir, k, "shots.json")))
    .map((key) => ({ key, json: JSON.parse(fs.readFileSync(path.join(dir, key, "shots.json"), "utf8")) }));
}

/* ---------- main ---------- */

function main() {
  const bundle = buildBundle(readRounds(), new Date().toISOString().slice(0, 10));
  const out = JSON.stringify(bundle, null, 2) + "\n";
  if (process.argv.includes("--check")) {
    const prev = fs.existsSync(OUT_PATH) ? fs.readFileSync(OUT_PATH, "utf8") : null;
    // "generated" changes daily; compare with that one field normalized out (as build-profile does).
    const norm = (s) => s && s.replace(/"generated": "[^"]*"/, '"generated": "GENERATED"');
    if (norm(prev) !== norm(out)) {
      console.error("import-shotpattern --check: src/shotpattern.json is stale. Run `npm run import:shots`.");
      process.exit(1);
    }
    console.log("import-shotpattern --check: src/shotpattern.json is up to date.");
    return;
  }
  fs.writeFileSync(OUT_PATH, out);
  const n = bundle.rounds.reduce((a, r) => a + r.records.length, 0);
  console.log(`import-shotpattern: ${bundle.rounds.length} round(s), ${n} records → src/shotpattern.json`);
  for (const r of bundle.rounds) {
    if (r.holesShort.length) console.log(`  ${r.key}: rows short of the score on ${r.holesShort.map((h) => `H${h.hole} (${h.strokes}/${h.score})`).join(", ")}`);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
